add('hailaer-new-yexue','fun','野雪艺术空间','从古城文创组合中单独落实到一家可导航的店，毛毡和地域手作为主要看点。','小羊造型、毛毡、手工小物。','按喜好和预算选择，手作品库存随时变化。','D1 或 D6 城区用餐后合并短逛。',r(G,'实逛野雪家，认可原创毛毡物品。'),r(H,'古城文创购物中点名野雪的小羊。'))
add('hailaer-new-yuanfang','fun','远方来信文创店','两篇实逛游记点名，适合与野雪比较后再选纪念品。','毛毡类小物与地域文创。','同一次逛街不必把每家都买一遍。','D6 短逛备选，提前留足还车时间。',r(G,'认可远方来信文创品类。'),r(H,'实逛远方来信，点名毛毡瑞士卷。'))
add('hailaer-new-petersburg','eat','彼得堡餐厅','一篇实吃游记认可环境、份量和味道，可与卢布里二选一。','俄餐；依据正文没有编造具体招牌菜。','菜量较大，先问份量；目前只有单篇支持。','D1 或 D6 城区正餐备选。',r(H,'实际用餐后认为环境好、菜量大，是该次海拉尔饮食体验中较喜欢的一家。'))
add('morigle-new-qushui','play','曲水云天','从北线组合里落实到明确的观景点，多篇实走反馈支持河曲全景。','在开放观景范围内看曲流。','高德显示它偏离目前的游客中心主线，不能把整个北线当零绕路；入场安排需当日确认。','D1 需在南线与北线玩法之间取舍，页面距离是保留现有途经点再加入本点。',r('6a86d86f000000003301180b','推荐北线曲水云天的高处视角。'),r('6890bf6500000000030268f4','明确建议到图嘎和曲水一带。'),r(AL,'实走图嘎到曲水观景区，认可河曲视野。'),r(AM,'实到曲水云天，认可登高后河道全景。'))
add('morigle-new-tuga','drink','图嘎营地 · 固定补给点','核到固定营地，可休息或购买饮品；口味证据仍不足。','点饮品前问清和观景入场的关系。','两篇重点在消费与观景便利，未给明确好喝评价，所以推荐票保持 0。','D1 仅在选择北线时考虑；不为一杯饮品专门绕路。',r(AL,'记录图嘎营地喝茶与观景消费安排，未评价茶味。','mention'),r(AM,'记录在图嘎买奶茶和点心，重点是观景便利。','mention'))
add('morigle-new-mabeishan','play','马背山','从北线线路中拆出的具体高处视角，但不是顺手几分钟的小停靠。','按开放道路到观景位置看草原与曲水。','加入现有 D1 主线所需驾驶明显增加；天气、路况与开放规则决定是否值得去。','D1 还要前往根河，优先选少量核心点。',r('6a86d86f000000003301180b','明确推荐马背山附近的北线视角。'),r('68c8c01a000000001b02184b','认可马背山草原与落日。'),r(AL,'实际到马背山一带，认可景色层次。'))
add('eerguna-new-fuji','eat','福记列巴坊','有实际购买记录，适合买少量列巴作为路上补给。','脆皮列巴或带果干的列巴。','另一位作者对冰淇淋没有很高评价，别把列巴好评扩大到所有产品；出炉批次现场问。','D5 回城或 D6 出发前。',r(AK,'实际购买热脆皮列巴，认可外酥里软。'),r('6a368941000000000702e473','实吃后喜欢带果干的列巴，冰淇淋未达到预期。'))
add('eerguna-new-mingyuan','eat','铭源特色餐厅','有详细实吃反馈的手把肉备选，适合喜欢清水煮羊肉的人。','手把肉，原帖具体点了羊排。','肥瘦、嚼劲因部位与个人口味而异，点菜前说明偏好。','D5 晚餐备选；D1 赶路先问出菜时间。',r(F,'实吃清水手把羊排，评价好、份量足。'))
add('eerguna-new-baohualin','play','白桦林景区 · 停车场入口','具体景区有亲访支持，但高德对照显示偏离当前额尔古纳主线，需要额外留时间。','到入口后按当天开放安排林间步行和观景。','来源是夏季体验，十月树叶与项目开放不能保证；已安排鹿园时不必重复喂鹿。','D1／D5／D6 都有后续任务，属于可放弃的支线。',r('68878a440000000013011a1f','实际乘景交进入白桦林，认可拍照和亲子游玩。'))
add('genhe-new-shouwang','play','守望桥','把原来泛指河畔的一项落实到桥这一固定地标。','在开放桥面与步道看河流、夕照。','不同笔记季节不同，晨雾和日落不是必得效果。','D1 晚到则略过；D2 早起按路况短停。',r(I,'明确推荐守望桥看日落与附近步道。'),r(J,'追秋游记点名守望桥。'),r('68745ff8000000002201fea5','实到守望桥，认为桥上视角看根河很美。'))
add('aoluguya-new-museum','play','敖鲁古雅鄂温克族驯鹿文化博物馆','高德核到具体文化场馆，现有笔记只是提及，尚不足以评价展览。','有兴趣可先询问开放与参观安排。','不把使鹿部落整体好评自动记给博物馆。','D2 原景区附近，适合不想重复动物互动的人比较。',r('69216be7000000001e026619','正文末列出博物馆，没有实际展陈评价。','mention'))
add('mordaga-new-longshan','play','龙山公园 · 步行看镇景与林海','新增 9 月亲访记录认可小镇与林海视野，适合抵达后按体力选择步行深度。','短走看镇景规划 45–75 分钟；完整登顶往返规划 90–120 分钟。9 月 24 日作者约 6:10 开始爬、8:00 回到山门，含山顶停留，支持给完整往返留足时间。','高德仅核到公园 POI，未核独立步行入口；导航到附近后问清开放步道。有 9 月 25 日作者反馈后山驾车道路坑洼、狭窄，不照搬驾车登顶路线；天黑前下山。','D2 到镇较早、天气和步道允许时选短走；完整登顶需另留 1.5–2 小时，不为日落赶山路。',r('6a7adc7a0000000025002da9','旧帖建议天气好可去，但作者因雪未去，只保留行程提及。','mention'),r('6abcf5190000000013019618','9 月 27 日亲访龙山，认可安静看小镇的体验，记录为免费景点。'),r('6aaf4129000000002a006b29','9 月 20 日发布的实走记录明确推荐最高观景台及林海视野。'),r('6ab4b79f0000000018028366','9 月 24 日记录步行上下山与山顶停留时间，认可镇景和周围森林全景。'),r('6ab6565b000000000b007b40','9 月 25 日亲自驾车上山后强烈不建议开车登顶，反馈坑洼窄路与会车困难；只针对这条驾车方式，非步行景观差评。','mixed'))
add('genhe-new-juele','fun','觉乐驯鹿园 · 喂鹿替代','有 10 月 2 日到访自述及其他亲访支持，推荐作为神鹿园恢复未核实时的替代；若已在敖鲁古雅喂鹿可跳过。','规划停留 60–90 分钟。10 月 2 日笔记记录停留约 1 小时、门票 35 元、苔藓 20 元，均为该次体验信息，非当前报价保证。','未电话确认 10 月 3 日营业，高德只核到景区 POI，未核独立停车入口。2025 年 9 月有单篇自述被鹿角碰伤的负反馈，未独立核实；注意鹿角并按工作人员指引互动，不据此断定当前普遍情况。','D2 放在根河出发端，与敖鲁古雅喂鹿二选一；驾驶增量看本轮高德证据，不套用笔记出租车里程。',r('6abfd4b100000000180154a8','10 月 2 日行程自述在觉乐停留 1 小时，认可少人、互动与拍照体验；价格只作到访记录。'),r('6ab2d042000000000b0078b2','实际在觉乐互动后明确喜欢驯鹿，描述喂食和观察反刍的体验。'),r('6aaa6dfa000000002601ce9b','9 月 16 日实访记录票价、喂食和时段差异，包含鹿角提醒；主要提供实用信息，不额外计推荐票。','mention'),r('6abb9f49000000001802d826','实到觉乐，记录园子小、鹿活泼及位置，明确好评的是园旁湿地白桦林；不把周边风景好评计作鹿园推荐。','mention'),r('68d0a86a000000001202e576','2025 年 9 月 22 日单篇自述喂鹿时被鹿角碰伤及处理体验不佳；历史个人经历，未独立核实。','negative'))
add('deerbur-new-station','play','得耳布尔站 · 站前外观','近期作者实际步行到车站并欣赏林区小镇景观，可作午餐后的小停靠。','规划 10–15 分钟看站房外观与周边公共街道，感受林区小镇的老建筑。','仅安排站前外观，不承诺进入站台或铁路作业区域；不在轨道拍照。原帖历史与列车信息未单独核验，不作为乘车指南。','D2 得耳布尔午餐后有余量再加；导航驾驶增量与步行停留分别计算。',r('6ab79e38000000000a02514d','作者实地步行到得耳布尔站，认可沿途林业遗存和小镇晚霞，支持站前周边短走。'))
add('bailudao-new-linxi','eat','太平林场 · 林曦农家菜','有详细实吃记录，高德核到太平林场桥头；是白鹿岛去临江途中的餐厅，不在白鹿岛本岛。','当地蔬菜、家常东北菜，按当天菜单点。','一篇明确支持，菜量大；不要把另一篇未具名的太平私房饭算给这家。','D4 白鹿岛→临江路段途中午餐备选，可与临江午餐二选一。',r('68d95f900000000012023085','实际在太平林曦农家菜用餐，认可食材、锅气和份量。'))
add('linjiang-new-northhill','play','临江村晨雾观景点','核到独立观景 POI，和神仙坡分开比较，避免把两个坡当同一处。','在开放路径看临江村落和河谷。','晨雾看天气；不依据车辙上陡坡。你的 D4 是白天途经，不能承诺看到晨雾。','D4 中午有余量可看村落全景，不为清晨照片改变行程。',r('68cbcc2a000000001203cf03','实际登北坡看村庄与晨雾。'),r('6aa81f2a00000000260319da','记录北坡清晨景色，天空颜色与晨雾随天气变化。'))
add('linjiang-new-shenxian','play','界河观景点（神仙坡）','三篇有明确日落或界河观景体验，高德落点可与当前过境线路对照。','从开放位置看界河河曲，白天也可短看。','不穿越围栏；页面只计算到高德落点的驾驶，不包含登坡。','D4 白天经过，不等日落，以免耽误七卡。',r('6aa81f2a00000000260319da','实际到神仙坡，认可日落光线照在界河上。'),r('68920228000000002501933f','明确导航神仙坡并登高看日落。'),r('66eab14a000000001e018a4c','行程中实际到临江神仙坡看日落。'))
