add('genhe-new-linzhongxian','eat','林中鲜小串 · 幸福家园店','新帖写出“小串”店名，与高德一致；实吃反馈认可烤串，也有菜品偏咸的保留意见。','羊肉串、肉筋、拌鸡架，按人数少量加点。','一位作者觉得盐焗鸡爪太咸，整体只给中等评价；不把个别烤串好评扩大到全菜单。','D1 根河晚餐备选；D2 出发前不专门等烧烤营业。',r('6a58d6120000000011017afe','根河餐厅清单点名林中鲜烧烤。'),r(N4,'明确写林中鲜小串，认可肉筋羊肉，但鸡爪偏咸，整体三分评价。','mixed'),r(N8,'实吃林中鲜烧烤，认可口味、性价比与拌鸡架。'))
add('genhe-new-xindingyuan','eat','鑫鼎园大铜锅','两篇不同作者的实吃记录支持，适合希望吃清涮羊肉的正餐。','铜锅涮羊肉，先问肉品部位与份量。','一篇是冬季游记，营业时间和当日供应需现问；份量按同行人数调整。','D1 到根河后，与酸菜排骨锅或烧烤二选一。',r(I,'根河游记明确推荐鑫鼎园铜锅火锅。'),r(N7,'实际吃鑫鼎园大铜锅，认为羊肉好吃。'))
add('mordaga-new-jiemei','eat','姐妹酒家 · 河东一道街店','既有实吃好评，也有近期对点单价格与服务不满的反馈；虽靠近路线，仍按有分歧处理。','好评作者点锅包肉、地三鲜，建议少点避免浪费。','差评作者反映未看清菜单、鱼价和服务体验不佳；这是个人经历，未独立核实。点单前确认菜单、份量和总价。','D2／D3 镇上备选，优先和红姐砂锅、雅娟比较。',r(N2,'实吃认可东北菜、老式锅包肉和地三鲜，提醒份量大。'),r(N6,'亲测合集列出河东一道街店，但没有单店详细口味描述。','mention'),r('6aabd79100000000260385b5','近期实吃对菜单展示、鱼价及服务体验强烈不满；作为负面反馈保留，不据此断定违规事实。','negative'))
add('mordaga-new-yajuan','eat','雅娟家常菜','作者晚饭临时换店后的实际反馈，几道家常菜评价积极，可作镇上正餐备选。','排骨炖豆角、野菜煎蛋、鱼香茄子。','目前单篇参考，作者提到鱼香茄子偏酸甜；镇上晚饭尽量别拖太晚。','D2 抵达后用餐；D3 离镇前先确认开门。',r(N3,'实际在雅娟吃饭，认可排骨炖豆角与野菜煎蛋，茄子是酸甜口。'))
add('mordaga-new-jihe','drink','几何精品咖啡与茶','新帖给出镇内明确店名，高德核到店铺；现有文字不足以判断咖啡品质。','按当天菜单挑咖啡或茶，先问营业。','来源仅列店名，没有具体饮品实喝评价，推荐作者数保持 0。','D2／D3 镇内短休候选，不必为此专程绕行。',r(N6,'合集点名几何精品咖啡与茶，没有单独饮品描述。','mention'))
add('mordaga-new-hulaoda','eat','胡老大铁锅炖 · 地点待核对','三位作者写到同名餐厅，尤其认可大鹅和贴饼；高德暂未返回该店独立 POI，严格核点筛选下隐藏。','大鹅锅、玉米饼；同行人数少时先问小份。','菜量偏大，炖制需要时间；一位作者认为牛肉一般。不能用隔壁咖啡馆的坐标代替餐厅。','D2 晚餐线索，先确认餐厅位置和等菜时间再安排。',r(N4,'认可大鹅与玉米饼，建议提前炖、多人分享。'),r(N7,'认可贴饼与白菜，牛肉表现一般。'),r('68e09d2400000000070392a9','明确在莫尔道嘎胡老大吃炖大鹅，认为嫩、香且份量大。'))
add('shiwei-new-yogurt','drink','河畔牧场酸奶屋','一篇实际购买记录给出清晰品种，可作为室韦停靠时的奶食补给。','咸炒米酸奶、奶皮子酸奶，奶豆可少量试口味。','目前单篇支持；咸酸奶和炒米口感有个人偏好，带走需考虑保存条件。','D4 室韦短停顺带购买，比再安排一顿正餐轻便。',r(N8,'实际购买并明确推荐咸炒米酸奶、奶皮子酸奶和奶豆。'))
add('shiwei-new-mumin-tea','drink','牧民的日常 · 甜奶茶','把饮品和正餐分开判断：同一作者不喜欢冰煮羊，但明确喜欢甜奶茶。','甜奶茶；奶皮卷可按口味少量尝试。','单篇饮品支持，不能理解为整店菜品都好；到店若排队长就换补给。','D4 室韦短停，先问能否只点饮品。',r(N5,'明确觉得甜奶茶好喝，奶皮卷也不错；未把正餐的负评归到饮品。'))
add('heishantou-new-yunxi','eat','云汐小馆','一篇跨城实吃游记认可菜品和份量，高德核到镇内明确商铺。','按当天菜单点家常热菜；正文未写具体菜名，不虚构招牌。','单篇支持，份量较大，先问出菜速度。','D5 黑山头活动前后用餐，留足回额尔古纳车程。',r(N7,'实吃认为云汐小馆菜好、量大，也喜欢锅茶。'))
add('heishantou-new-yunxi-tea','drink','云汐小馆 · 锅茶','同一实吃作者明确夸锅茶，作为正餐一起点的热饮选择。','锅茶，点之前问一锅份量。','单篇支持，与餐厅卡片是同一家店，不重复计作两个固定地点。','D5 若在本店吃饭可合并体验。',r(N7,'实际点锅茶，明确评价好喝。'))
add('heishantou-new-ziyu','eat','子昱饭店 · 黑山头新镇','作者尤其喜欢炒羊杂，但觉得羊排性价比不高，适合有选择地点菜。','炒羊杂，其他菜先看菜单。','同一作者对茶香羊排有保留，不把炒羊杂的好评扩大到羊排；仅一篇来源。','D5 镇内正餐备选，与一品香、云汐择一。',r(N1,'炒羊杂评价积极，但茶香羊排的性价比不符预期。','mixed'))
add('heishantou-new-mengniu','eat','蒙妞图娅 · 奶食购买','两位作者对不同奶食品种的喜好有差异，更适合顺路少量试吃。','烤奶皮配蓝莓酱、奶豆腐，能试吃再选。','一位喜欢烤奶皮但不喜欢牛奶，另一位认可奶豆腐却认为不值得专程来；不按必买店推荐。','D5 路过且营业时短停，别挤占草原活动时间。',r(N1,'喜欢烤奶皮加蓝莓酱，但牛奶不合口味。','mixed'),r(N4,'奶豆腐尚可，整体认为无需特意前往。','mixed'))

add('mordaga-new-hongdoupo','play','红豆坡 · 落叶松林间步道','近期自驾笔记认可高大落叶松与林间步道，适合慢走拍照。','规划停留 30–45 分钟；这是行程估时，原帖未给单点耗时。','园内道路能否自驾通行和步道开放以入口当天确认为准；十月叶色与天气变化快，不承诺满林金黄。','D3 上午与一目九岭合并作为园内自驾方案，可替换小火车；停车、步行与驾驶分别计时。',r('6ab928f0000000000a020cd0','作者自驾园内，明确认可红豆坡高大落叶松与林间步道体验。'))
add('mordaga-new-yimujiuling','play','一目九岭 · 林海观景台','近期自驾作者特别推荐登高看层叠林海，适合与红豆坡一起安排。','规划停留 45–60 分钟，按开放步道登观景台；这是计划估时，非景区保证时长。','原帖提醒猎人之路出口在公路、需折返停车场；时间紧可不走这条延伸步道。登高视野受天气及当日开放影响。','D3 红豆坡后登高，再转往白鹿岛；和小火车完整游览择一。',r('6ab928f0000000000a020cd0','作者登观景台，明确推荐层叠林海视野，并提醒猎人之路折返耗时。'))
add('bailudao-new-rafting','fun','白鹿岛短线漂流','两篇近期亲历都提到短线约 1 小时，适合当天开行时从水上看森林。','漂流本身参考约 1 小时，连购票、准备与接驳规划预留 1.5–2 小时；出发前确认返程安排。','是否开行、末班、天气及接驳需当天确认；有作者午间等了约 1 小时，不能保证随到随漂。原帖价格仅属到访记录，不作为当前报价。','D3 下午与河湾观景搭配；时间不足或停航时改为开放步道短走。近期另有长线约 2.5 小时的体验，不混作短线时长。',r('6abd1b580000000012034cc9','亲自体验短线约 1 小时，认可沿河森林景色和下船后林荫路。'),r('6aba1746000000001403af31','实漂长线约 2.5 小时，途经短线终点约 1 小时；认可悠闲观景，也记录午间等待约 1 小时。'))

add('shiwei-new-tuanjie','play','室韦团结广场 · 界河短停','近期自驾亲历认可广场看界河、对岸及蒙兀室韦地标的视角，适合作为室韦短停。','在开放公共观景区看界河，计划预留 20–30 分钟；这是游览估时，非原帖实测。','停车与开放区域以现场为准；不沿围栏缺口进入封闭河岸。能看到游船不等于包含乘船体验。','10 月 5 日临江午餐后途经室韦，和主街列巴采购合并，再往九卡、七卡。',r('6abe84e000000000020112e6','作者实际停靠室韦团结广场，推荐界河视野与蒙兀室韦地标，并提醒卡线规范停车。'))
add('shiwei-new-aoliya','eat','奥利亚列巴房 · 少量补给','有实际购买经典大列巴的好评；不同产品与服务体验有分歧，适合少量采购路上补给。','可先看经典大列巴；新帖作者认为好吃且个头大，人数少时少买。','新作者觉得服务态度平淡，另一篇对千层和华夫饼评价一般；不把大列巴好评扩大到全部产品。营业、排队与出炉时段未确认。','10 月 5 日室韦短停时与团结广场合并，控制采购时间，避免挤占九卡至七卡的白天行程。',r('6ac0bdd20000000012034392','作者 9 月 25 日实际购买经典大列巴，认可口味与份量，同时觉得营业态度平淡；按产品和服务分歧保留。','mixed'),r('6aab9cd40000000011038482','实际买过奥利亚千层和华夫饼，认为千层未达预期、华夫饼一般；不将其他店酸奶好评计入本店。','mixed'))

